use stucco::prelude::*;

fn main() {
    let bundle = Bundle::new(Preset::Slate);
    let html = Page::new(&bundle, "Hello, Stucco")
        .main(Container::new().child(Stack::new()
            .child(Heading::new(1, "Hello, Stucco"))
            .child(Text::new("Safe <text> & a page."))))
        .render();
    assert!(html.contains(r#"<main id="main">"#));
    assert!(html.contains(r##"href="#main""##));
    assert!(html.contains("Safe &lt;text&gt; &amp; a page."));
    println!("Verified the rendered document.");
}
